    if sign == "+":
        if max_value is not None:
            left_number = str(self.random_int(int(max(min_value or 0, 0)), int(max_value)))
        else:
            min_left_digits = math.ceil(math.log10(max(min_value or 1, 1)))
            if left_digits is None:
